import '../../../../../Global/Authentication/data/Models/user_data_model.dart';import '../models/update_password.dart';import '../models/update_user.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';class UserDataSources {  static Future<UpdateUser> updateUserData(      {required UpdateUser updateUser}) async {    final response = await DioHelper.postData(      data: updateUser.toMap(),      path: ApiEndpoints.updateUser,    );    return UpdateUser.fromMap(response.data["data"]);  }  static Future<bool> updatePassword({required UpdatePassword updateUser}) async {    final response = await DioHelper.postData(      data: updateUser.toMap(),      path: ApiEndpoints.changePassword,    );    if (response.statusCode != 200) {      return false;    }    return true;  }  static Future<UserDataModel> getUserData() async {    final response = await DioHelper.getData(      path: ApiEndpoints.getUser,    );    return UserDataModel.fromJson((response.data["user"]));  }}